import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.Cdp8-jB6.js";const m=JSON.parse('{"title":"Module README guide — small tactical docs next to code","description":"","frontmatter":{},"headers":[],"relativePath":"guides/module-readme-guide.md","filePath":"guides/module-readme-guide.md"}'),n={name:"guides/module-readme-guide.md"};function s(r,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="module-readme-guide-—-small-tactical-docs-next-to-code" tabindex="-1">Module README guide — small tactical docs next to code <a class="header-anchor" href="#module-readme-guide-—-small-tactical-docs-next-to-code" aria-label="Permalink to &quot;Module README guide — small tactical docs next to code&quot;">​</a></h1><p>How to write a <strong>module map</strong>: a short README that sits next to the code it describes and carries the local knowledge the code alone cannot state. It serves everyone the same way — humans and agents, feature work and maintenance. This guide is for anyone (especially agents) adding or extending one.</p><p>Live examples in this repo: <a href="./../../src/lib/ar/README"><code>src/lib/ar/README.md</code></a> · <a href="./../../scripts/README"><code>scripts/README.md</code></a> · <a href="./../../tests/e2e/README"><code>tests/e2e/README.md</code></a>.</p><h2 id="when-to-write-one" tabindex="-1">When to write one <a class="header-anchor" href="#when-to-write-one" aria-label="Permalink to &quot;When to write one&quot;">​</a></h2><p>Any one trigger is enough:</p><ul><li>The area has <strong>two or more look-alike implementations</strong> (same concept, different consumers) and nothing states which serves what.</li><li>A <strong>convention</strong> exists that code doesn&#39;t declare: units, coordinate frames, physical models, naming/taxonomy rules, generated-vs-source boundaries.</li><li>A fix or review <strong>went to the wrong file or layer</strong> in this area — that miss is the signal that local knowledge is undocumented.</li><li>A folder has grown enough files that &quot;what lives where&quot; needs answering.</li></ul><h2 id="where-it-lives" tabindex="-1">Where it lives <a class="header-anchor" href="#where-it-lives" aria-label="Permalink to &quot;Where it lives&quot;">​</a></h2><p><code>README.md</code> inside the module&#39;s folder; for a single top-level file, <code>&lt;name&gt;.README.md</code> next to it. Always adjacent to the code so it moves, versions, and gets reviewed together with what it describes.</p><h2 id="what-goes-in-10–25-lines-whichever-of-these-apply" tabindex="-1">What goes in (10–25 lines, whichever of these apply) <a class="header-anchor" href="#what-goes-in-10–25-lines-whichever-of-these-apply" aria-label="Permalink to &quot;What goes in (10–25 lines, whichever of these apply)&quot;">​</a></h2><ol><li><strong>One line: what this area is</strong> and which route/feature consumes it.</li><li><strong>Ownership map</strong> — file/function → responsibility → consumer.</li><li><strong>Disambiguation</strong> — name the look-alikes and when to use which.</li><li><strong>Local conventions &amp; invariants</strong> — units, frames, models, taxonomy rules, &quot;generated — don&#39;t hand-edit&quot; boundaries.</li><li><strong>Contracts callers rely on.</strong></li><li><strong>Pointers up</strong> — one line each to the ADR / PRD / RFC / TA.md section that holds the <em>why</em>. Link, never summarize: the README carries the <em>what / which / who-owns</em>; the big docs carry the <em>why</em>. If the why isn&#39;t written anywhere, flag the gap — don&#39;t invent it here.</li></ol><h2 id="what-stays-out" tabindex="-1">What stays out <a class="header-anchor" href="#what-stays-out" aria-label="Permalink to &quot;What stays out&quot;">​</a></h2><ul><li>Bug/ticket/PR references and history (&quot;added for #123&quot; rots).</li><li>API reference — signatures and types live in the code.</li><li>Roadmap/strategy — belongs in the docs you link to.</li><li>Anything the code already says clearly. Non-obvious only.</li><li>More than ~25 lines. Longer means the area needs splitting, or the content is really an ADR.</li></ul><p>Voice: a maintainer leaving notes for the next person; present tense. The README states the module&#39;s <em>intended</em> conventions — if code contradicts the doc, that divergence is a bug to raise and fix (same anti-drift rule as TA.md), never something to paper over.</p><h2 id="validating-a-module-readme" tabindex="-1">Validating a module README <a class="header-anchor" href="#validating-a-module-readme" aria-label="Permalink to &quot;Validating a module README&quot;">​</a></h2><ul><li><strong>Review checklist (2 min).</strong> Someone who has never seen the area must be able to answer from the README alone: <em>which file/function do I touch for a symptom here? which of the look-alikes, and why not the other? what invariant must my change respect?</em> Plus: ≤25 lines, zero bug references, links to big docs rather than copies. Any miss → rewrite.</li><li><strong>Localization quiz (empirical).</strong> Give an agent a vague-but-honest bug description for the area and ask &quot;which file/function would you change, and what must the fix respect?&quot; — once without the README, once with it. The doc is load-bearing iff the with-doc answer names the right target and constraints when the without-doc answer did not.</li></ul><p>Hindsight caveat: a README written by someone who knows a specific bug can smuggle the answer. Stick to module-intent facts (ownership, conventions, contracts) a maintainer would write regardless; never describe any bug&#39;s symptom or fix.</p>',16)])])}const g=t(n,[["render",s]]);export{m as __pageData,g as default};
